89|          '现金流充裕，分红稳定',
90|          '管理层优秀，战略清晰',
91|          '研发投入大，创新驱动'
92|        ]
93|        // 为示例页面提供 30 个「股票代码 → 中文名称」的对应关系，用中文公司名而不是「股票3」这类占位符
94|        const baseNames = [
95|          '浦发银行', '白云机场', '华夏银行', '宝钢股份', '中国石化',
96|          '中信证券', '中国国航', '上海机场', '万科A', '招商银行',
97|          '中国平安', '贵州茅台', '五粮液', '伊利股份', '中国中免',
98|          '宁德时代', '比亚迪', '隆基绿能', '海天味业', '迈瑞医疗',
99|          '海康威视', '汇川技术', '立讯精密', '三一重工', '中国建筑',
100|          '中国联通', '中国电信', '中国移动', '紫金矿业', '东方财富'
101|        ]
102|
103|        for (let i = 1; i <= 30; i++) {
104|          const code = `600${i.toString().padStart(3, '0')}`
105|          // 股票名称使用与代码一一对应的中文公司名，避免「股票3」这类占位符
106|          const name = baseNames[i - 1] || `示例股票${i}`
107|          const price = (Math.random() * 100 + 10).toFixed(2)
108|          const change = (Math.random() * 10 - 5).toFixed(2)
109|          const limitUpProbability = (Math.random() * 40 + 30).toFixed(1)
110|          const industry = industries[Math.floor(Math.random() * industries.length)]
111|          const marketValue = (Math.random() * 1000 + 100).toFixed(0)
112|          const pe = (Math.random() * 50 + 10).toFixed(1)
113|          const reason = reasons[Math.floor(Math.random() * reasons.length)]
114|
115|          stocks.push({
116|            code,
117|            name,
118|            price: parseFloat(price),
119|            change: parseFloat(change),
120|            limitUpProbability: parseFloat(limitUpProbability),
121|            industry,
122|            marketValue: parseFloat(marketValue),
123|            pe: parseFloat(pe),
124|            recommendReason: reason
125|          })
126|        }
127|
128|        this.stockList = stocks
129|      } finally {
130|        this.loading = false
131|      }
132|    },
133|    handleStockClick (stock) {
